package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.learning.courseprogress.v1.*;
/** Participant-only Group-space progress. Course metadata/participation stay in Collaboration. */
final class CourseProgressStore {
 record Step(UUID studyId,String status) {}
 record Progress(UUID progressId,UUID groupId,UUID spaceId,UUID courseId,UUID participantId,long version,long courseVersion,UUID enrollmentId,long enrollmentVersion,String visibility,String audience,List<Step> steps,String updatedAt) {}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Progress snapshot) {}
 record History(List<Revision> items,Long nextBefore) {}
 static final Set<String> STATUSES=Set.of("NOT_STARTED","IN_PROGRESS","COMPLETED");
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 CourseProgressStore(DataSource source,Clock clock){sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 Progress get(CourseContextClient.Reference ref){var rows=sql.query("SELECT snapshot::text FROM group_course_progress WHERE group_id=? AND space_id=? AND course_id=? AND participant_id=?",(rs,n)->json.readValue(rs.getString(1),Progress.class),ref.groupId(),ref.spaceId(),ref.courseId(),ref.principalId());if(!rows.isEmpty()){var v=rows.getFirst();if(!v.steps().stream().map(Step::studyId).toList().equals(ref.studies().stream().map(CourseContextClient.Study::studyId).toList()))throw error(HttpStatus.CONFLICT,"Course curriculum changed");return v;}return new Progress(null,ref.groupId(),ref.spaceId(),ref.courseId(),ref.principalId(),0,ref.courseVersion(),ref.enrollmentId(),ref.enrollmentVersion(),"PRIVATE","PARTICIPANT_ONLY",ref.studies().stream().map(s->new Step(s.studyId(),"NOT_STARTED")).toList(),null);}
 Progress change(CourseContextClient.Reference ref,UUID study,long expected,String status,String trace){CourseContextClient.validate(ref);RoadmapGraph.id(study);if(expected<0||status==null||!STATUSES.contains(status)||trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw RoadmapGraph.bad();if(!ref.writable())throw error(HttpStatus.CONFLICT,"Current enrollment and writable Course required");if(ref.studies().stream().noneMatch(s->s.studyId().equals(study)))throw error(HttpStatus.NOT_FOUND,"Study is not in this Course");
  return tx.execute(s->{String scope=ref.spaceId()+":"+ref.courseId()+":"+ref.principalId();sql.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",rs->{},scope);var old=get(ref);if(old.version()!=expected)throw error(HttpStatus.PRECONDITION_FAILED,"Progress changed; refresh current version");var prior=old.steps().stream().filter(step->step.studyId().equals(study)).findFirst().orElseThrow();if(prior.status().equals(status))return old;
   String now=clock.instant().truncatedTo(ChronoUnit.MICROS).toString();var steps=old.steps().stream().map(step->step.studyId().equals(study)?new Step(study,status):step).toList();var v=new Progress(old.progressId()==null?ids.next():old.progressId(),ref.groupId(),ref.spaceId(),ref.courseId(),ref.principalId(),Math.addExact(old.version(),1),ref.courseVersion(),ref.enrollmentId(),ref.enrollmentVersion(),"PRIVATE","PARTICIPANT_ONLY",steps,now);
   if(old.version()==0)sql.update("INSERT INTO group_course_progress VALUES (?,?,?,?,?,?,?::jsonb)",v.progressId(),v.groupId(),v.spaceId(),v.courseId(),v.participantId(),v.version(),json.writeValueAsString(v));else sql.update("UPDATE group_course_progress SET version=?,snapshot=?::jsonb WHERE progress_id=?",v.version(),json.writeValueAsString(v),v.progressId());record(v,trace);return v;
  });
 }
 History history(CourseContextClient.Reference ref,long before,int limit){var v=get(ref);if(v.progressId()==null)return new History(List.of(),null);var rows=sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM group_course_progress_revision WHERE progress_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Progress.class)),v.progressId(),before,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new History(items,rows.size()>limit?items.getLast().version():null);}
 private void record(Progress v,String trace){var at=Timestamp.from(Instant.parse(v.updatedAt()));sql.update("INSERT INTO group_course_progress_revision VALUES (?,?,?,?,?,?::jsonb)",ids.next(),v.progressId(),v.version(),v.participantId(),at,json.writeValueAsString(v));var p=CourseProgressSnapshotV1.newBuilder().setProgressId(v.progressId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setCourseId(v.courseId().toString()).setParticipantId(v.participantId().toString()).setVersion(v.version()).setCourseVersion(v.courseVersion()).setEnrollmentId(v.enrollmentId().toString()).setEnrollmentVersion(v.enrollmentVersion()).setVisibility(v.visibility()).setAudience(v.audience()).setUpdatedAt(v.updatedAt());for(var step:v.steps())p.addSteps(CourseStudyProgressV1.newBuilder().setStudyId(step.studyId().toString()).setStatus(step.status()));UUID id=ids.next();var e=CourseProgressEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType("CourseStudyProgressChanged").setEventVersion(1).setOccurredAtEpochMillis(Instant.parse(v.updatedAt()).toEpochMilli()).setProducer("learning-service").setAggregateType("CourseProgress").setAggregateId(v.progressId().toString()).setSpaceId(v.spaceId().toString()).setActorId(v.participantId().toString()).setTraceId(trace).setPayload(p.build().toByteString()).build();sql.update("INSERT INTO outbox_event (id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'course-progress',?,'CourseStudyProgressChanged',?,?,'learning','course-progress-events','1',?)",id,v.progressId(),at,trace,e.toByteArray());}
}
